/**
 * Nyayota AI — Streaming Natural Conversational Response Engine (Phase 8)
 * 
 * Delivers progressive, source-grounded legal intelligence streams using Server-Sent Events (SSE).
 * 
 * Core Features:
 * 1. Progressive Delivery: Streams text tokens as generated by Gemini with low TTFT.
 * 2. Strict Statutory Grounding: Anchors stream to verified in-repo statutory records.
 * 3. Incremental Sanitization: Sliding lookback window guards against prompt leak and advocate impersonation across chunk boundaries.
 * 4. Deterministic Fallback: Seamlessly transitions to deterministic engine on upstream timeout, quota error, or offline state.
 * 5. Cancellation & Resource Cleanup: Honors AbortSignal to immediately abort upstream calls and close stream.
 * 6. Multilingual Continuity: Preserves Bengali, English, and Banglish terminology.
 * 7. Zero Information Leakage: Never emits raw internal system prompts or API keys.
 */

import {
  ConversationContext,
  RoutingDecision,
} from './types';
import {
  DeterministicSourceCitation,
  LegalRetrievalResponse,
  DeterministicLegalResponse,
} from '../types';
import {
  buildSystemInstruction,
  formatGeminiContents,
  getOrCreateGenAiClient,
} from './natural-response-engine';
import { handleConversationalTurn } from './conversation-handler';
import { AI_CONFIG } from '../../ai-config';

// ============================================================================
// 1. STREAM EVENT TYPES & PROTOCOL
// ============================================================================

export type LegalStreamEventType =
  | 'start'
  | 'metadata'
  | 'token'
  | 'completed'
  | 'fallback'
  | 'error';

export interface StreamStartEventData {
  id: string;
  query: string;
  mode: string;
  language: string;
  timestamp: string;
}

export interface StreamMetadataEventData {
  provider: string;
  model: string;
  generationMethod: 'gemini-streaming' | 'deterministic-fallback';
  sources: DeterministicSourceCitation[];
  disclaimer: string;
  disclaimerBn?: string;
  headline?: string;
  headlineBn?: string;
}

export interface StreamTokenEventData {
  delta: string;
}

export interface StreamCompletedEventData {
  fullText: string;
  textBn?: string;
  headline: string;
  headlineBn?: string;
  summary: string;
  summaryBn?: string;
  executionTimeMs: number;
}

export interface StreamFallbackEventData {
  reason: string;
  text: string;
  textBn?: string;
  headline: string;
  headlineBn?: string;
  summary: string;
  summaryBn?: string;
  sources: DeterministicSourceCitation[];
  disclaimer: string;
  disclaimerBn?: string;
  executionTimeMs: number;
}

export interface StreamErrorEventData {
  code: string;
  message: string;
}

export interface LegalStreamEvent {
  event: LegalStreamEventType;
  data:
    | StreamStartEventData
    | StreamMetadataEventData
    | StreamTokenEventData
    | StreamCompletedEventData
    | StreamFallbackEventData
    | StreamErrorEventData;
}

export interface StreamingResponseEngineInput {
  query: string;
  context: ConversationContext;
  decision: RoutingDecision;
  targetLanguage?: 'en' | 'bn' | 'both';
  retrievalResponse?: LegalRetrievalResponse;
  sources?: DeterministicSourceCitation[];
  deterministicResponse?: DeterministicLegalResponse;
  apiKey?: string;
  model?: string;
  timeoutMs?: number;
  signal?: AbortSignal;
  /** Optional custom or mocked GenAI client for isolated deterministic testing */
  genAiClient?: any;
}

// ============================================================================
// 2. INCREMENTAL SANITIZER (BOUNDARY-SAFE BUFFERED DEFENSE)
// ============================================================================

/**
 * System prompt leak signatures and impersonation patterns to neutralize.
 */
const FORBIDDEN_STREAM_PATTERNS = [
  /PRIMARY DIRECTIVES & BOUNDARIES:?/gi,
  /STRICT LEGAL GROUNDING:?/gi,
  /SECURITY MANDATE FOR DATA EVALUATION:?/gi,
  /You are the natural conversational voice of Nyayota/gi,
  /<statutory_record[^>]*>/gi,
  /<\/statutory_record>/gi,
  /\bI am your (attorney|lawyer|advocate|legal counsel|legal representative)\b/gi,
  /\bAs your (attorney|lawyer|advocate|legal counsel)\b/gi,
  /\bI (will|can) represent you in court\b/gi,
];

const ADVOCATE_NEUTRALIZATION_REPLACEMENT =
  'Nyayota is an educational legal research assistant and cannot act as legal counsel';

/**
 * Incremental sanitizer maintaining a safe lookback buffer (~120 chars)
 * across chunk boundaries to prevent split malicious tokens or prompt leaks.
 */
export class IncrementalSanitizer {
  private buffer = '';
  private emittedLength = 0;
  private readonly lookbackWindow: number;

  constructor(lookbackWindow = 36) {
    this.lookbackWindow = lookbackWindow;
  }

  /**
   * Appends an incoming raw chunk, scrubs forbidden patterns,
   * and returns the safe-to-emit text prefix.
   */
  public processChunk(chunk: string): string {
    if (!chunk) return '';
    this.buffer += chunk;

    // Apply neutralization patterns across current buffer
    this.applyNeutralizations();

    if (this.buffer.length > this.lookbackWindow) {
      const emitSliceEnd = this.buffer.length - this.lookbackWindow;
      const safePrefix = this.buffer.slice(0, emitSliceEnd);
      this.buffer = this.buffer.slice(emitSliceEnd);
      this.emittedLength += safePrefix.length;
      return safePrefix;
    }

    return '';
  }

  /**
   * Flushes any remaining characters at the end of the stream
   * after applying a final sanitization pass.
   */
  public flush(): string {
    this.applyNeutralizations();
    const finalChunk = this.buffer;
    this.buffer = '';
    this.emittedLength += finalChunk.length;
    return finalChunk;
  }

  private applyNeutralizations(): void {
    // 1. Strip prompt leaks
    this.buffer = this.buffer.replace(/PRIMARY DIRECTIVES & BOUNDARIES:?/gi, '');
    this.buffer = this.buffer.replace(/STRICT LEGAL GROUNDING:?/gi, '');
    this.buffer = this.buffer.replace(/SECURITY MANDATE FOR DATA EVALUATION:?/gi, '');
    this.buffer = this.buffer.replace(/You are the natural conversational voice of Nyayota/gi, '');
    this.buffer = this.buffer.replace(/<statutory_record[^>]*>/gi, '');
    this.buffer = this.buffer.replace(/<\/statutory_record>/gi, '');

    // 2. Neutralize advocate impersonation
    this.buffer = this.buffer.replace(
      /\bI am your (attorney|lawyer|advocate|legal counsel|legal representative)\b/gi,
      ADVOCATE_NEUTRALIZATION_REPLACEMENT
    );
    this.buffer = this.buffer.replace(
      /\bAs your (attorney|lawyer|advocate|legal counsel)\b/gi,
      ADVOCATE_NEUTRALIZATION_REPLACEMENT
    );
    this.buffer = this.buffer.replace(
      /(and\s+will|I\s+will|I\s+can|\bwill|\bcan)\s+represent\s+you\s+in\s+court\b/gi,
      ADVOCATE_NEUTRALIZATION_REPLACEMENT
    );
  }
}

// ============================================================================
// 3. STREAMING GENERATION CORE
// ============================================================================

const EDUCATIONAL_DISCLAIMER_EN =
  'Notice: Nyayota provides educational legal research only and does not constitute formal legal representation or legal advice.';
const EDUCATIONAL_DISCLAIMER_BN =
  'সতর্কবার্তা: ন্যায়তা শুধুমাত্র শিক্ষামূলক আইনি গবেষণার তথ্য প্রদান করে এবং এটি আনুষ্ঠানিক আইনি প্রতিনিধিত্ব বা পরামর্শ নয়।';

/**
 * Async generator producing typed LegalStreamEvents for a conversation turn.
 */
export async function* generateLegalStream(
  input: StreamingResponseEngineInput
): AsyncGenerator<LegalStreamEvent, void, unknown> {
  const startTime = Date.now();
  const requestId = `nyayota-${startTime}-${Math.random().toString(36).substring(2, 9)}`;

  const {
    query,
    context,
    decision,
    targetLanguage = 'both',
    sources = [],
    deterministicResponse,
    apiKey = process.env.GEMINI_API_KEY,
    model = AI_CONFIG.model,
    timeoutMs = AI_CONFIG.timeoutMs,
    signal,
    genAiClient,
  } = input;

  // 1. Emit Start Event
  yield {
    event: 'start',
    data: {
      id: requestId,
      query,
      mode: decision.responseMode,
      language: targetLanguage,
      timestamp: new Date().toISOString(),
    },
  };

  // Check if caller already requested cancellation
  if (signal?.aborted) {
    yield {
      event: 'error',
      data: {
        code: 'ABORTED',
        message: 'Client aborted the request before streaming began.',
      },
    };
    return;
  }

  // 2. Validate Gemini capability
  const isValidApiKey = Boolean(apiKey && apiKey !== 'MY_GEMINI_API_KEY' && !apiKey.startsWith('test') && apiKey.length > 10);
  const canUseGemini = Boolean(isValidApiKey || genAiClient);

  if (!canUseGemini) {
    // Graceful fallback to deterministic engine
    const fallback = synthesizeFallbackOutput(query, context, decision, sources, deterministicResponse, targetLanguage, startTime);
    yield {
      event: 'metadata',
      data: {
        provider: 'nyayota-deterministic',
        model: 'deterministic-v2',
        generationMethod: 'deterministic-fallback',
        sources: fallback.sources,
        disclaimer: fallback.disclaimer,
        disclaimerBn: fallback.disclaimerBn,
        headline: fallback.headline,
        headlineBn: fallback.headlineBn,
      },
    };

    // Emit tokens in chunked deltas
    const chunks = chunkTextSafely(fallback.text, 24);
    for (const chunk of chunks) {
      if (signal?.aborted) return;
      yield {
        event: 'token',
        data: { delta: chunk },
      };
    }

    yield {
      event: 'completed',
      data: {
        fullText: fallback.text,
        textBn: fallback.textBn,
        headline: fallback.headline,
        headlineBn: fallback.headlineBn,
        summary: fallback.summary,
        summaryBn: fallback.summaryBn,
        executionTimeMs: Date.now() - startTime,
      },
    };
    return;
  }

  // 3. Attempt Gemini Streaming Generation
  try {
    const ai = genAiClient || getOrCreateGenAiClient(apiKey!);
    const systemInstruction = buildSystemInstruction(context, decision, sources, targetLanguage);
    const contents = formatGeminiContents(query, context);

    yield {
      event: 'metadata',
      data: {
        provider: 'google-genai',
        model,
        generationMethod: 'gemini-streaming',
        sources,
        disclaimer: targetLanguage === 'bn' ? EDUCATIONAL_DISCLAIMER_BN : EDUCATIONAL_DISCLAIMER_EN,
        disclaimerBn: EDUCATIONAL_DISCLAIMER_BN,
        headline: decision.responseMode === 'clarification' ? 'Clarification Required' : 'Statutory Analysis',
        headlineBn: decision.responseMode === 'clarification' ? 'স্পষ্টীকরণ প্রয়োজন' : 'সংবিধিবদ্ধ আইনি বিশ্লেষণ',
      },
    };

    const sanitizer = new IncrementalSanitizer();
    let accumulatedText = '';

    // Execute with timeout wrapper
    let timedOut = false;
    const timeoutHandle = setTimeout(() => {
      timedOut = true;
    }, timeoutMs);

    try {
      const responseStream = await ai.models.generateContentStream({
        model,
        contents,
        config: {
          systemInstruction,
        },
      });

      for await (const chunk of responseStream) {
        if (signal?.aborted) {
          clearTimeout(timeoutHandle);
          yield {
            event: 'error',
            data: { code: 'ABORTED', message: 'Stream aborted by client.' },
          };
          return;
        }

        if (timedOut) {
          throw new Error(`Generation timed out after ${timeoutMs / 1000}s`);
        }

        const rawChunkText = (chunk as any)?.text || '';
        if (rawChunkText) {
          accumulatedText += rawChunkText;
          const safeDelta = sanitizer.processChunk(rawChunkText);
          if (safeDelta.length > 0) {
            yield {
              event: 'token',
              data: { delta: safeDelta },
            };
          }
        }
      }

      clearTimeout(timeoutHandle);

      // Flush remaining sanitized buffer
      const finalDelta = sanitizer.flush();
      if (finalDelta.length > 0) {
        yield {
          event: 'token',
          data: { delta: finalDelta },
        };
      }

      // Check for completely empty response
      const completeCleanedText = accumulatedText.trim();
      if (!completeCleanedText) {
        throw new Error('Gemini returned an empty response body.');
      }

      yield {
        event: 'completed',
        data: {
          fullText: completeCleanedText,
          headline: 'Statutory Research Findings',
          headlineBn: 'সংবিধিবদ্ধ গবেষণার ফলাফল',
          summary: completeCleanedText.slice(0, 150) + (completeCleanedText.length > 150 ? '...' : ''),
          executionTimeMs: Date.now() - startTime,
        },
      };
    } catch (primaryError: unknown) {
      clearTimeout(timeoutHandle);
      const errMsg = primaryError instanceof Error ? primaryError.message : 'Unknown generation error';

      // Fallback to deterministic synthesis
      const fallback = synthesizeFallbackOutput(
        query,
        context,
        decision,
        sources,
        deterministicResponse,
        targetLanguage,
        startTime
      );

      yield {
        event: 'fallback',
        data: {
          reason: errMsg,
          text: fallback.text,
          textBn: fallback.textBn,
          headline: fallback.headline,
          headlineBn: fallback.headlineBn,
          summary: fallback.summary,
          summaryBn: fallback.summaryBn,
          sources: fallback.sources,
          disclaimer: fallback.disclaimer,
          disclaimerBn: fallback.disclaimerBn,
          executionTimeMs: Date.now() - startTime,
        },
      };
    }
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : 'Unexpected streaming failure';
    yield {
      event: 'error',
      data: {
        code: 'INTERNAL_STREAM_ERROR',
        message,
      },
    };
  }
}

// ============================================================================
// 4. SSE FORMATTING & WEB RESPONSE ADAPTER
// ============================================================================

/**
 * Formats a single LegalStreamEvent into a standard SSE protocol string.
 * Uses strict CRLF / LF line conventions without leaking internal instructions.
 */
export function formatSSEMessage(event: LegalStreamEvent): string {
  const dataString = JSON.stringify(event.data);
  return `event: ${event.event}\ndata: ${dataString}\n\n`;
}

/**
 * Creates a standard W3C ReadableStream<Uint8Array> suitable for Next.js Route Handlers.
 */
export function createLegalEventStream(input: StreamingResponseEngineInput): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder();

  return new ReadableStream<Uint8Array>({
    async start(controller) {
      try {
        for await (const streamEvent of generateLegalStream(input)) {
          const sseString = formatSSEMessage(streamEvent);
          controller.enqueue(encoder.encode(sseString));
        }
        controller.close();
      } catch (err) {
        controller.error(err);
      }
    },
    cancel() {
      // Stream consumer cancelled the read
    },
  });
}

/**
 * Produces an HTTP Response with appropriate streaming headers.
 */
export function createLegalStreamingResponse(input: StreamingResponseEngineInput): Response {
  const stream = createLegalEventStream(input);

  return new Response(stream, {
    status: 200,
    headers: {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      'Connection': 'keep-alive',
      'X-Accel-Buffering': 'no',
    },
  });
}

// ============================================================================
// 5. HELPER UTILITIES
// ============================================================================

function chunkTextSafely(text: string = '', chunkSize = 24): string[] {
  if (!text) return [];
  const chunks: string[] = [];
  let index = 0;
  while (index < text.length) {
    chunks.push(text.slice(index, index + chunkSize));
    index += chunkSize;
  }
  return chunks;
}

function synthesizeFallbackOutput(
  query: string,
  context: ConversationContext,
  decision: RoutingDecision,
  sources: DeterministicSourceCitation[],
  deterministicResponse: DeterministicLegalResponse | undefined,
  targetLanguage: string,
  startTime: number
) {
  if (deterministicResponse) {
    const text = (targetLanguage === 'bn' && deterministicResponse.structuredExplanationBn
      ? deterministicResponse.structuredExplanationBn
      : deterministicResponse.structuredExplanation) || deterministicResponse.summary || '';

    return {
      text,
      textBn: deterministicResponse.structuredExplanationBn,
      headline: deterministicResponse.headline,
      headlineBn: deterministicResponse.headlineBn,
      summary: deterministicResponse.summary,
      summaryBn: deterministicResponse.summaryBn,
      sources: deterministicResponse.sources || sources,
      disclaimer: deterministicResponse.disclaimer || EDUCATIONAL_DISCLAIMER_EN,
      disclaimerBn: deterministicResponse.disclaimerBn || EDUCATIONAL_DISCLAIMER_BN,
    };
  }

  const conv = handleConversationalTurn(decision, context);
  const primaryText = targetLanguage === 'bn' && conv.textBn ? conv.textBn : conv.text;

  return {
    text: primaryText,
    textBn: conv.textBn,
    headline: conv.headline,
    headlineBn: conv.headlineBn,
    summary: conv.summary,
    summaryBn: conv.summaryBn,
    sources,
    disclaimer: conv.disclaimer || EDUCATIONAL_DISCLAIMER_EN,
    disclaimerBn: EDUCATIONAL_DISCLAIMER_BN,
  };
}
